import { Link } from 'react-router-dom';
import { useEffect, useState } from 'react';
import { getApplications } from '../services/applicationService';
import { internships } from '../services/internshipService';
import { useAuth } from '../context/AuthContext';

function Dashboard() { const { user } = useAuth(); const [applications, setApplications] = useState([]); useEffect(() => { getApplications(user.uid).then(setApplications); }, [user.uid]); return <div><div className="page-enter flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-sm font-semibold text-blue-600">Student dashboard</p><h1 className="mt-1 text-2xl font-bold tracking-tight sm:text-3xl">Good to see you, {user.displayName || 'Student'}</h1><p className="mt-2 text-sm text-slate-600 sm:text-base">Keep moving toward your next professional milestone.</p></div><Link to="/internships" className="attention-glow w-full rounded-lg bg-blue-600 px-4 py-3 text-center text-sm font-semibold text-white hover:bg-blue-700 sm:w-auto">Explore internships</Link></div><div className="mt-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[['Applications', applications.length, '/applications'], ['Available roles', internships.length, '/internships'], ['Profile completion', '65%', '/profile'], ['Current status', applications[0]?.status || 'Explore', '/progress']].map(([label, value, path], index) => <Link key={label} to={path} style={{ animationDelay: `${index * 70}ms` }} className="page-enter card-lift rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200 hover:ring-blue-300"><p className="text-sm text-slate-500">{label}</p><p className="mt-3 text-2xl font-bold text-slate-900 sm:text-3xl">{value}</p><p className="mt-2 text-sm font-semibold text-blue-600">View details &rarr;</p></Link>)}</div><div className="mt-8 grid gap-6 lg:grid-cols-[1.2fr_0.8fr]"><section className="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200 sm:p-6"><div className="flex items-center justify-between gap-4"><h2 className="text-lg font-bold sm:text-xl">Recommended for you</h2><Link to="/internships" className="shrink-0 text-sm font-semibold text-blue-600">View all</Link></div><div className="mt-5 space-y-3">{internships.slice(0, 3).map((item) => <Link to={`/internships/${item.id}`} key={item.id} className="card-lift block rounded-xl border border-slate-200 p-4 hover:border-blue-300"><div className="flex flex-col gap-2 sm:flex-row sm:justify-between sm:gap-4"><div className="min-w-0"><h3 className="break-words font-semibold">{item.title}</h3><p className="mt-1 text-sm text-slate-500">{item.company} &middot; {item.location}</p></div><span className="text-sm font-semibold text-emerald-600">{item.stipend}</span></div></Link>)}</div></section><section className="rounded-2xl bg-slate-900 p-5 text-white sm:p-6"><p className="text-sm font-semibold text-blue-300">Your next step</p><h2 className="mt-3 text-xl font-bold sm:text-2xl">Complete your profile</h2><p className="mt-3 text-sm leading-6 text-slate-300">A complete profile helps companies understand your strengths and improves your recommendations.</p><Link to="/profile" className="mt-6 inline-block rounded-lg bg-white px-4 py-3 text-sm font-semibold text-slate-900">Update profile</Link></section></div></div>; }

export default Dashboard;