import { useEffect, useState } from 'react';
import { getProfile, saveProfile } from '../services/userService';
import { useAuth } from '../context/AuthContext';

function Profile() { const { user } = useAuth(); const [profile, setProfile] = useState({}); const [saved, setSaved] = useState(false); useEffect(() => { getProfile(user.uid, { name: user.displayName || '', email: user.email || '', education: '', location: '', skills: [], bio: '' }).then(setProfile); }, [user]); function change(event) { setProfile({ ...profile, [event.target.name]: event.target.value }); } async function submit(event) { event.preventDefault(); await saveProfile(user.uid, { ...profile, skills: profile.skillsText ? profile.skillsText.split(',').map((item) => item.trim()).filter(Boolean) : profile.skills }); setSaved(true); } return <div className="max-w-3xl"><h1 className="text-3xl font-bold">Your profile</h1><p className="mt-2 text-slate-600">Help companies understand your goals, education, and strengths.</p><form onSubmit={submit} className="mt-8 rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200 sm:p-8"><div className="grid gap-5 sm:grid-cols-2"><label className="text-sm font-semibold">Full name<input name="name" value={profile.name || ''} onChange={change} className="mt-2 w-full rounded-lg border border-slate-300 px-4 py-3 font-normal" /></label><label className="text-sm font-semibold">Email<input value={profile.email || ''} readOnly className="mt-2 w-full rounded-lg border border-slate-200 bg-slate-50 px-4 py-3 font-normal text-slate-500" /></label><label className="text-sm font-semibold">Education<input name="education" value={profile.education || ''} onChange={change} className="mt-2 w-full rounded-lg border border-slate-300 px-4 py-3 font-normal" /></label><label className="text-sm font-semibold">Location<input name="location" value={profile.location || ''} onChange={change} className="mt-2 w-full rounded-lg border border-slate-300 px-4 py-3 font-normal" /></label></div><label className="mt-5 block text-sm font-semibold">Skills <span className="font-normal text-slate-500">(comma separated)</span><input name="skillsText" value={profile.skillsText ?? (profile.skills || []).join(', ')} onChange={change} className="mt-2 w-full rounded-lg border border-slate-300 px-4 py-3 font-normal" /></label><label className="mt-5 block text-sm font-semibold">Short bio<textarea name="bio" value={profile.bio || ''} onChange={change} rows="4" className="mt-2 w-full rounded-lg border border-slate-300 px-4 py-3 font-normal" /></label>{saved && <p className="mt-4 text-sm text-emerald-700">Profile saved successfully.</p>}<button className="mt-6 rounded-lg bg-blue-600 px-5 py-3 font-semibold text-white hover:bg-blue-700">Save profile</button></form></div>; }

export default Profile;