import { useState } from 'react';

function Contact() {
  const [sent, setSent] = useState(false);
  const details = [['Email', 'hello@internpath.com'], ['Phone', '+91 XXXXXXXXXX'], ['Location', 'Bhubaneswar, Odisha, India'], ['Working hours', 'Monday – Friday, 9:00 AM – 6:00 PM']];
  const faqs = [['Who can use InternPath?', 'Students and fresh graduates looking for meaningful internship experience can get started with us.'], ['Are the internships verified?', 'We work to list relevant opportunities from companies and organisations we trust.'], ['How do I get started?', 'Send us a message or create your profile, then our team will help you explore the next steps.']];
  function handleSubmit(event) { event.preventDefault(); setSent(true); }
  return <><section className="bg-slate-950 py-20 text-center text-white sm:py-24"><div className="mx-auto max-w-3xl px-5"><p className="text-sm font-bold uppercase tracking-widest text-blue-400">Contact us</p><h1 className="mt-4 text-4xl font-bold tracking-tight sm:text-5xl">Let’s talk about your future.</h1><p className="mt-5 text-lg text-slate-300">Have a question or need guidance? Our team would love to hear from you.</p></div></section><section className="py-20"><div className="mx-auto grid max-w-7xl gap-12 px-5 lg:grid-cols-2 lg:px-8"><div><p className="text-sm font-bold uppercase tracking-widest text-blue-600">Get in touch</p><h2 className="mt-3 text-3xl font-bold tracking-tight">We’re here to help.</h2><p className="mt-4 max-w-md leading-7 text-slate-600">Reach out to ask about internships, career guidance or how InternPath can support you.</p><div className="mt-8 space-y-5">{details.map(([label, value]) => <div key={label} className="rounded-xl bg-white p-5 ring-1 ring-slate-200"><p className="text-sm font-semibold text-blue-600">{label}</p><p className="mt-1 font-medium text-slate-800">{value}</p></div>)}</div></div><form onSubmit={handleSubmit} className="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200 sm:p-8"><h2 className="text-2xl font-bold">Send a message</h2><p className="mt-2 text-sm text-slate-600">This form is ready for your future backend connection.</p><div className="mt-6 grid gap-5 sm:grid-cols-2"><label className="text-sm font-semibold">First name<input required className="mt-2 w-full rounded-lg border border-slate-300 px-4 py-3 font-normal outline-none focus:border-blue-600" placeholder="Your first name" /></label><label className="text-sm font-semibold">Last name<input required className="mt-2 w-full rounded-lg border border-slate-300 px-4 py-3 font-normal outline-none focus:border-blue-600" placeholder="Your last name" /></label></div><label className="mt-5 block text-sm font-semibold">Email<input required type="email" className="mt-2 w-full rounded-lg border border-slate-300 px-4 py-3 font-normal outline-none focus:border-blue-600" placeholder="you@example.com" /></label><label className="mt-5 block text-sm font-semibold">Message<textarea required rows="5" className="mt-2 w-full resize-none rounded-lg border border-slate-300 px-4 py-3 font-normal outline-none focus:border-blue-600" placeholder="How can we help?" /></label><button className="mt-6 w-full rounded-lg bg-blue-600 px-5 py-3.5 font-semibold text-white transition hover:bg-blue-700">Send Message</button>{sent && <p className="mt-4 text-center text-sm font-medium text-emerald-600">Thanks! Your message has been received.</p>}</form></div></section><section className="bg-white py-20"><div className="mx-auto max-w-3xl px-5"><div className="text-center"><p className="text-sm font-bold uppercase tracking-widest text-blue-600">FAQ</p><h2 className="mt-3 text-3xl font-bold tracking-tight">Frequently asked questions</h2></div><div className="mt-10 space-y-4">{faqs.map(([question, answer]) => <div key={question} className="rounded-xl border border-slate-200 p-6"><h3 className="font-bold text-slate-900">{question}</h3><p className="mt-2 leading-6 text-slate-600">{answer}</p></div>)}</div></div></section></>;
}

export default Contact;
