function SimplePage({ title, description, children }) { return <div><h1 className="text-3xl font-bold">{title}</h1><p className="mt-2 text-slate-600">{description}</p><div className="mt-8 rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200">{children}</div></div>; }

export function Stipend() { return <SimplePage title="Stipend" description="Review stipend information for your active internship."><p className="text-slate-600">Stipend details will appear here once you are selected for an internship.</p></SimplePage>; }
export function Certificate() { return <SimplePage title="Certificate" description="Access certificates earned through completed internships."><p className="text-slate-600">Complete an internship to receive your certificate here.</p></SimplePage>; }
export function Notifications() { return <SimplePage title="Notifications" description="Stay informed about applications and internship updates."><div className="border-b border-slate-200 pb-4"><p className="font-semibold">Welcome to InternPath</p><p className="mt-1 text-sm text-slate-600">Complete your profile to receive better internship recommendations.</p></div><p className="pt-4 text-sm text-slate-500">You are all caught up.</p></SimplePage>; }