import {
  createUserWithEmailAndPassword,
  GoogleAuthProvider,
  sendPasswordResetEmail,
  signInWithEmailAndPassword,
  signInWithPopup,
  signOut,
  updateProfile,
} from 'firebase/auth';
import { auth, isFirebaseConfigured } from './firebase';

const DEMO_USERS_KEY = 'internpath-demo-users';
const DEMO_SESSION_KEY = 'internpath-demo-session';

export const isDemoMode = !isFirebaseConfigured || !auth;

function readDemoUsers() {
  try {
    return JSON.parse(localStorage.getItem(DEMO_USERS_KEY) || '[]');
  } catch {
    return [];
  }
}

function demoUser({ id, name, email }) {
  return { uid: id, displayName: name, email, isDemoUser: true };
}

function readDemoSession() {
  try {
    const session = JSON.parse(localStorage.getItem(DEMO_SESSION_KEY) || 'null');
    return session ? demoUser(session) : null;
  } catch {
    return null;
  }
}

function saveDemoSession(user) {
  localStorage.setItem(DEMO_SESSION_KEY, JSON.stringify({
    id: user.uid,
    name: user.displayName,
    email: user.email,
  }));
}

export function getStoredUser() {
  return isDemoMode ? readDemoSession() : null;
}

export async function signIn(email, password) {
  if (isDemoMode) {
    const account = readDemoUsers().find((user) => user.email.toLowerCase() === email.toLowerCase() && user.password === password);
    if (!account) throw new Error('Email or password is incorrect. Create a demo account first.');
    const user = demoUser(account);
    saveDemoSession(user);
    return user;
  }
  const result = await signInWithEmailAndPassword(auth, email, password);
  return result.user;
}

export async function signUp({ name, email, password }) {
  if (isDemoMode) {
    const users = readDemoUsers();
    if (users.some((user) => user.email.toLowerCase() === email.toLowerCase())) {
      throw new Error('An account with this email already exists. Please sign in.');
    }
    const account = { id: `demo-${Date.now()}`, name: name.trim(), email: email.trim(), password };
    localStorage.setItem(DEMO_USERS_KEY, JSON.stringify([...users, account]));
    const user = demoUser(account);
    saveDemoSession(user);
    return user;
  }
  const result = await createUserWithEmailAndPassword(auth, email, password);
  await updateProfile(result.user, { displayName: name });
  return result.user;
}

export async function signInWithGoogle() {
  if (isDemoMode) throw new Error('Google sign-in is unavailable in demo mode. Use a demo email and password instead.');
  const result = await signInWithPopup(auth, new GoogleAuthProvider());
  return result.user;
}

export async function resetPassword(email) {
  if (isDemoMode) {
    if (!readDemoUsers().some((user) => user.email.toLowerCase() === email.toLowerCase())) {
      throw new Error('No demo account exists for this email address.');
    }
    return undefined;
  }
  return sendPasswordResetEmail(auth, email);
}

export async function logout() {
  if (isDemoMode) {
    localStorage.removeItem(DEMO_SESSION_KEY);
    return;
  }
  await signOut(auth);
}
