import { addDoc, collection, getDocs, query, where } from 'firebase/firestore';
import { db, isFirebaseConfigured } from './firebase';

const DEMO_APPLICATIONS_KEY = 'internpath-demo-applications';

function readDemoApplications() {
  try {
    return JSON.parse(localStorage.getItem(DEMO_APPLICATIONS_KEY) || '[]');
  } catch {
    return [];
  }
}

export async function getApplications(uid) {
  if (!isFirebaseConfigured || !db) return readDemoApplications().filter((application) => application.userId === uid);
  const snapshot = await getDocs(query(collection(db, 'applications'), where('userId', '==', uid)));
  return snapshot.docs.map((item) => ({ id: item.id, ...item.data() }));
}

export async function createApplication(application) {
  if (!isFirebaseConfigured || !db) {
    const applications = readDemoApplications();
    if (applications.some((item) => item.userId === application.userId && item.internshipId === application.internshipId)) {
      throw new Error('You have already applied for this internship.');
    }
    const created = { id: `demo-application-${Date.now()}`, ...application };
    localStorage.setItem(DEMO_APPLICATIONS_KEY, JSON.stringify([...applications, created]));
    return created;
  }
  const existingApplications = await getApplications(application.userId);
  if (existingApplications.some((item) => item.internshipId === application.internshipId)) {
    throw new Error('You have already applied for this internship.');
  }
  const result = await addDoc(collection(db, 'applications'), application);
  return { id: result.id, ...application };
}
