import { doc, getDoc, setDoc } from 'firebase/firestore';
import { db, isFirebaseConfigured } from './firebase';

const DEMO_PROFILES_KEY = 'internpath-demo-profiles';

function readDemoProfiles() {
  try {
    return JSON.parse(localStorage.getItem(DEMO_PROFILES_KEY) || '{}');
  } catch {
    return {};
  }
}

export async function getProfile(uid, fallback = {}) {
  if (!isFirebaseConfigured || !db) return { ...fallback, ...readDemoProfiles()[uid] };
  const snapshot = await getDoc(doc(db, 'users', uid));
  return snapshot.exists() ? snapshot.data() : fallback;
}

export async function saveProfile(uid, profile) {
  if (!isFirebaseConfigured || !db) {
    const profiles = readDemoProfiles();
    const savedProfile = { ...profiles[uid], ...profile };
    localStorage.setItem(DEMO_PROFILES_KEY, JSON.stringify({ ...profiles, [uid]: savedProfile }));
    return savedProfile;
  }
  await setDoc(doc(db, 'users', uid), profile, { merge: true });
  return profile;
}
