import { Link } from 'react-router-dom';
import { useMemo, useState } from 'react';
import { internships } from '../services/internshipService';

function Internships() { const [search, setSearch] = useState(''); const [category, setCategory] = useState('All'); const categories = ['All', ...new Set(internships.map((item) => item.category))]; const filtered = useMemo(() => internships.filter((item) => (category === 'All' || item.category === category) && `${item.title} ${item.company} ${item.skills.join(' ')}`.toLowerCase().includes(search.toLowerCase())), [search, category]); return <div><h1 className="text-2xl font-bold sm:text-3xl">Find your next internship</h1><p className="mt-2 text-sm text-slate-600 sm:text-base">Search verified opportunities matched to your goals.</p><div className="mt-6 flex flex-col gap-3 sm:flex-row"><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search roles, companies, or skills" className="min-w-0 flex-1 rounded-lg border border-slate-300 bg-white px-4 py-3 outline-none focus:border-blue-600" /><select value={category} onChange={(event) => setCategory(event.target.value)} className="w-full rounded-lg border border-slate-300 bg-white px-4 py-3 sm:w-auto">{categories.map((item) => <option key={item}>{item}</option>)}</select></div><div className="mt-8 grid gap-5 md:grid-cols-2">{filtered.map((item, index) => <article key={item.id} style={{ animationDelay: `${index * 70}ms` }} className="page-enter card-lift rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200 sm:p-6"><div className="flex flex-col items-start gap-3 sm:flex-row sm:items-start sm:justify-between"><div className="min-w-0"><span className="text-xs font-bold uppercase tracking-widest text-blue-600">{item.category}</span><h2 className="mt-2 break-words text-lg font-bold sm:text-xl">{item.title}</h2><p className="mt-1 text-sm text-slate-500">{item.company} &middot; {item.location}</p></div><span className="max-w-full rounded-full bg-emerald-50 px-3 py-1 text-xs font-semibold text-emerald-700">{item.stipend}</span></div><p className="mt-4 text-sm leading-6 text-slate-600">{item.description}</p><div className="mt-4 flex flex-wrap gap-2">{item.skills.map((skill) => <span key={skill} className="rounded-full bg-slate-100 px-3 py-1 text-xs font-medium text-slate-600">{skill}</span>)}</div><Link to={`/internships/${item.id}`} className="mt-5 inline-block font-semibold text-blue-600">View details &rarr;</Link></article>)}</div>{filtered.length === 0 && <div className="mt-8 rounded-2xl border border-dashed border-slate-300 bg-white p-8 text-center text-slate-600 sm:p-10">No internships match your search.</div>}</div>; }

export default Internships;