import { Link, useNavigate, useParams } from 'react-router-dom';
import { useState } from 'react';
import { createApplication } from '../services/applicationService';
import { getInternship } from '../services/internshipService';
import { useAuth } from '../context/AuthContext';

function InternshipDetails() { const { id } = useParams(); const item = getInternship(id); const { user } = useAuth(); const navigate = useNavigate(); const [error, setError] = useState(''); const [sent, setSent] = useState(false); if (!item) return <div className="rounded-2xl bg-white p-10 text-center">Internship not found. <Link className="font-semibold text-blue-600" to="/internships">Browse roles</Link></div>; async function apply(event) { event.preventDefault(); setError(''); try { await createApplication({ userId: user.uid, internshipId: item.id, title: item.title, company: item.company, status: 'Submitted', appliedAt: new Date().toISOString() }); setSent(true); } catch (err) { setError(err.message); } } return <div className="max-w-4xl"><Link to="/internships" className="text-sm font-semibold text-blue-600">&larr; Back to internships</Link><div className="mt-5 rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200 sm:p-8"><span className="text-sm font-bold uppercase tracking-widest text-blue-600">{item.category}</span><h1 className="mt-3 text-3xl font-bold">{item.title}</h1><p className="mt-2 text-slate-500">{item.company} &middot; {item.location} &middot; {item.duration}</p><div className="mt-8 grid gap-6 sm:grid-cols-3"><div><p className="text-sm text-slate-500">Stipend</p><p className="mt-1 font-semibold">{item.stipend}</p></div><div><p className="text-sm text-slate-500">Work mode</p><p className="mt-1 font-semibold">{item.location}</p></div><div><p className="text-sm text-slate-500">Skills</p><p className="mt-1 font-semibold">{item.skills.join(', ')}</p></div></div><h2 className="mt-10 text-xl font-bold">About the role</h2><p className="mt-3 leading-7 text-slate-600">{item.description}</p>{sent ? <div className="mt-8 rounded-xl bg-emerald-50 p-4 text-emerald-800">Application submitted. Track it from My Applications.<button onClick={() => navigate('/applications')} className="ml-2 font-semibold underline">View applications</button></div> : <form onSubmit={apply} className="mt-8 border-t border-slate-200 pt-8"><h2 className="text-xl font-bold">Application form</h2><label className="mt-4 block text-sm font-semibold">Why are you a good fit?<textarea required rows="4" className="mt-2 w-full rounded-lg border border-slate-300 px-4 py-3 font-normal outline-none focus:border-blue-600" placeholder="Share your motivation and relevant skills." /></label>{error && <p role="alert" className="mt-4 text-sm text-rose-700">{error}</p>}<button className="mt-5 rounded-lg bg-blue-600 px-5 py-3 font-semibold text-white hover:bg-blue-700">Submit application</button></form>}</div></div>; }

export default InternshipDetails;